import { useRef } from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";

function Hero() {
  const container = useRef(null);

  useGSAP(
    () => {
      const tl = gsap.timeline({ defaults: { ease: "power2.out" } });

      tl.from(".title", { y: 40, opacity: 0, duration: 0.6 })
        .from(".subtitle", { y: 20, opacity: 0, duration: 0.5 }, "-=0.3")
        .from(".cta", { scale: 0.9, opacity: 0, duration: 0.4 }, "-=0.2");
    },
    { scope: container },
  );

  return (
    <section ref={container}>
      <h1 className="title">Ship faster</h1>
      <p className="subtitle">Everything you need</p>
      <button className="cta">Start</button>
    </section>
  );
}

useGSAP(
  () => {
    gsap.from(".reveal", {
      opacity: 0,
      y: 30,
      duration: 0.6,
      stagger: 0.1,
      scrollTrigger: {
        trigger: container.current,
        start: "top 80%",
      },
    });
  },
  { scope: container },
);
